from .collectable import CollectableObject
from taf.internal.managedobject import ManagedObject
from .startable import StartableObject
import os


class Collector(ManagedObject, CollectableObject):
    """
    Collector.
    """


class StartableCollector(StartableObject, Collector):
    """
    Startable collector.
    """


class PostprocessingCollector(Collector):
    """
    Postprocessing Collector to handle the local executor attribute.
    """

    def __init__(self, local_executor, **kwargs):
        """
        Create Postprocessing based collector.

        :param Executor local_executor: object, which allows to execute commands on the local host
        """
        super(PostprocessingCollector, self).__init__(**kwargs)
        self._local_executor = local_executor


class CommandCollector(PostprocessingCollector):
    """
    Command based collector.

    Collector, that collects information from source locations by
    executing commands on remote hosts via SSH and transferring the remote files
    to the local host via scp or sftp, where they optionally may be postprocessed.
    """

    def __init__(self, tool_executor, file_getter, **kwargs):
        """
        Create command based collector.

        :param Executor tool_executor: object, which allows to execute commands on a remote host
        :param FileGetter file_getter: object, which allows to get files from a remote host to the local host
        """
        super(CommandCollector, self).__init__(**kwargs)
        self._tool_executor = tool_executor
        self.add_prerequisite(tool_executor)
        self._file_getter = file_getter
        self.add_prerequisite(file_getter)


class StartableCommandCollector(StartableObject, CommandCollector):
    """
    Startable command based collector.
    """


