class Decorating(object):
    """
    Decorating another collector with current one. It is Mix-in/Mixed-in class. Mixing-in class should be subclass of
    Collector.

    Example:
        Class XyCollector(Decorating, XyCollectorBase):
            ...

    Here three classes are involved:
        -> the decorated collector (subclass of Collector) or Decorating.collector
        -> the decorating collector (subclass of Collector, mixing-in class) or XyCollectorBase
        -> the "Decorating" class (mixed-in class)
    """

    def __init__(self, collector=None, **kwargs):
        """
        Adding given collector instance as prerequisite
        """
        super(Decorating, self).__init__(**kwargs)
        self._collector = collector
        if self._collector is not None:
            self.add_prerequisite(self._collector)

    @property
    def collector(self):
        return self._collector

    def __getattr__(self, name):
        if self._collector is not None and hasattr(self._collector, name):
            return getattr(self._collector, name)
        else:
            raise AttributeError(
                "'{cls}' object has no attribute '{name}'".format(
                    cls=self.__class__.__name__,
                    name=name))

    def _collect(self, target_dir):
        self._collector._collect(target_dir=target_dir)

    def _start(self):
        self._collector._start()

    def _stop(self):
        self._collector._stop()


class ScriptInstalling(object):
    """
    Adds Script upload, setup and teardown steps. It is Mix-in/Mixed-in class. Mixin-in class should be subclass of
    Collector. This class expects following parameters which should be available/initialized by Mixin-in class:
        self._tool_executor : tool executor for command execution
        self._file_putter : file putter for script upload

    Example:
        Class XyCollector(ScriptInstalling, XyCollectorBase):
            ...

    """

    def __init__(
            self,
            script_paths,
            script_dir,
            **kwargs):
        super(ScriptInstalling, self).__init__(**kwargs)
        self._script_paths = script_paths
        self._script_dir = script_dir

    def _setup(self):
        self._check_if_dir_exists()
        if not self._dir_exists:
            self._tool_executor.execute(
                "mkdir -p '{script_dir}'".format(script_dir=self._script_dir).encode())
        for script_path in self._script_paths:
            script_name = os.path.basename(script_path)
            self._file_putter.put_file(source_path=script_path,
                                       target_path="{script_dir}/{script_name}".format(script_dir=self._script_dir,
                                                                                       script_name=script_name))
            self._tool_executor.execute(
                "chmod +x '{script_dir}/{script_name}'".format(script_dir=self._script_dir,
                                                               script_name=script_name).encode())
        super(ScriptInstalling, self)._setup()

    def _teardown(self):
        super(ScriptInstalling, self)._teardown()
        for script_path in self._script_paths:
            script_name = os.path.basename(script_path)
            self._tool_executor.execute(
                "rm -f '{script_dir}/{script_name}'".format(script_dir=self._script_dir,
                                                            script_name=script_name).encode())
        if not self._dir_exists:
            self._tool_executor.execute(
                "rm -r '{script_dir}'".format(script_dir=self._script_dir).encode())

    def _check_if_dir_exists(self):
        _, _, exit_code = self._tool_executor.raw_execute('[ -d "{}" ]'.format(self._script_dir).encode())
        self._dir_exists = not exit_code


class Preparable(object):
    """
    Adds setup and teardown optional commands. It is Mix-in/Mixed-in class. Mixin-in class should be subclass of
    Collector. This class expects following parameters which should be available/initialized by Mixin-in class:
        self._tool_executor : tool executor for command execution

    Example:
        Class XyCollector(Preparable, XyCollectorBase):
            ...

    """

    def __init__(
            self,
            setup_commands=None,
            teardown_commands=None,
            **kwargs):
        super(Preparable, self).__init__(**kwargs)
        self._setup_commands = setup_commands or []
        self._teardown_commands = teardown_commands or []

    def _setup(self):
        for setup_command in self._setup_commands:
            self._tool_executor.execute(setup_command.encode())
        super(Preparable, self)._setup()

    def _teardown(self):
        super(Preparable, self)._teardown()
        for teardown_command in self._teardown_commands:
            self._tool_executor.execute(teardown_command.encode())
